import React, { useState } from 'react';

// Create the Accordion component here
const Accordion = () => {
  // Initialize accordionData array here
  const accordionData = [
    { title: 'Section 1', content: 'Content for section 1' },
    { title: 'Section 2', content: 'Content for section 2' },
    { title: 'Section 3', content: 'Content for section 3' }
  ];

  // Initialize openIndexes state here
  const [openIndexes, setOpenIndexes] = useState([]);

  // Create toggle handler function here
  const toggleItem = (index) => {
    setOpenIndexes(prev => 
      prev.includes(index) 
        ? prev.filter(i => i !== index)
        : [...prev, index]
    );
  };

  return (
    <div className="accordion">
      {/* Map through accordionData here */}
      {accordionData.map((item, index) => (
        // Add clickable header div here
        <div key={index} className="accordion-item">
          <div 
            className="accordion-header" 
            onClick={() => toggleItem(index)}
          >
            {item.title}
          </div>
          {/* Add content div with conditional rendering here */}
          {openIndexes.includes(index) && (
            <div className="accordion-content">
              {item.content}
            </div>
          )}
        </div>
      ))}
    </div>
  );
};
